package br.com.confirmacao.patient.api;import br.com.confirmacao.patient.domain.*;import java.time.*;import java.util.UUID;public record PatientResponse(UUID id,UUID professionalId,String professionalName,String professionalEmail,String professionalRegistrationNumber,String fullName,LocalDate birthDate,String phone,String email,PreferredContactChannel preferredChannel,ConsentStatus consentStatus,Instant consentedAt,boolean whatsappRemindersEnabled,Instant whatsappRemindersUpdatedAt,String whatsappRemindersSource,boolean active,Instant createdAt,Instant updatedAt){public static PatientResponse from(Patient p){return new PatientResponse(p.getId(),p.getProfessional().getId(),p.getProfessional().getFullName(),p.getProfessional().getEmail(),p.getProfessional().getRegistrationNumber(),p.getFullName(),p.getBirthDate(),p.getPhone(),p.getEmail(),p.getPreferredChannel(),p.getConsentStatus(),p.getConsentedAt(),p.isWhatsappRemindersEnabled(),p.getWhatsappRemindersUpdatedAt(),p.getWhatsappRemindersSource(),p.isActive(),p.getCreatedAt(),p.getUpdatedAt());}}
